INSERT INTO `products` (`ProductID`, `SellerID`, `ProductName`, `Price`, `Amount`, `Discount`, `Description`, `Category`) VALUES
('PR1', 'SE1', 'Metal Art Kyōjurō Rengoku', 50000.00, 1, 5.00, 'Metal Art Kyōjurō Rengoku is a stunning handcrafted piece inspired by the fiery spirit of Rengoku Kyōjurō, the Flame Hashira from Demon Slayer: Kimetsu no Yaiba. Forged with precision, the artwork captures his bold energy and unwavering determination. The metal surface brings out intricate details of his iconic flame-patterned haori, fierce gaze, and heroic posture. With a polished, flame-toned finish, the piece radiates strength, courage, and passion, making it a perfect tribute to Rengoku\'s legendary character and an eye-catching centerpiece for any anime or metal art collection.', 'art'),
('PR2', 'SE1', 'Metal Art Kyōjurō Rengoku', 55000.00, 1, 20.00, 'Metal Art Kyōjurō Rengoku is a stunning handcrafted piece inspired by the fiery spirit of Rengoku Kyōjurō, the Flame Hashira from Demon Slayer: Kimetsu no Yaiba. Forged with precision, the artwork captures his bold energy and unwavering determination. The metal surface brings out intricate details of his iconic flame-patterned haori, fierce gaze, and heroic posture. With a polished, flame-toned finish, the piece radiates strength, courage, and passion, making it a perfect tribute to Rengoku\'s legendary character and an eye-catching centerpiece for any anime or metal art collection.', 'art'),
('PR3', 'SE1', 'Metal Art Ryomen Sukuna', 85000.00, 1, 10.00, 'Bring the raw power of the King of Curses to your space with this premium metal wall art featuring Ryomen Sukuna from Jujutsu Kaisen. Crafted with precision laser-cut detailing and finished in sleek matte black with crimson accents, this piece radiates intensity and style. Perfect for anime fans, collectors, or anyone looking to add a touch of dark elegance to their decor.\r\n\r\n🔥 Material: High-quality stainless steel / alloy with anti-rust coating\r\n\r\n📐 Size: 18 x 24 inches (custom sizes available)\r\n\r\n🎨 Finish: Matte black base with optional red highlights\r\n\r\n🧲 Mounting: Easy wall-mount setup included (magnet or screw mount)\r\n\r\n✨ Vibe: Dark, powerful, aesthetic — a true centerpiece\r\n\r\n💀 Unleash the curse. Hang the legend.', 'art'),
('PR4', 'SE1', 'Metal Art Kyōjurō Rengoku', 105000.00, 1, 10.00, 'Metal Art Kyōjurō Rengoku is a stunning handcrafted piece inspired by the fiery spirit of Rengoku Kyōjurō, the Flame Hashira from Demon Slayer: Kimetsu no Yaiba. Forged with precision, the artwork captures his bold energy and unwavering determination. The metal surface brings out intricate details of his iconic flame-patterned haori, fierce gaze, and heroic posture. With a polished, flame-toned finish, the piece radiates strength, courage, and passion, making it a perfect tribute to Rengoku\'s legendary character and an eye-catching centerpiece for any anime or metal art collection.', 'art'),
('PR5', 'SE1', 'Metal Art Gojo', 125000.00, 1, 10.00, 'Step into the limitless domain of style with this sleek metal wall art featuring Satoru Gojo, the most powerful sorcerer from Jujutsu Kaisen. Designed with high-precision laser cuts and a bold contrast finish, this piece captures Gojo’s iconic blindfolded stare and effortless confidence. Whether you’re building an anime-themed setup or just want that one eye-catching statement piece — this is it.\r\n\r\n⚔️ Material: Durable stainless steel with protective matte coating\r\n\r\n📏 Dimensions: 18 x 24 inches (custom sizes available)\r\n\r\n🖤 Design: Infinity motif background with high contrast detailing\r\n\r\n🛠️ Mounting: Wall-ready with secure hooks or magnet backing\r\n\r\n💫 Aura: Minimalist, clean, and insanely cool — just like Gojo\r\n\r\n👁 \"Throughout Heaven and Earth, I alone am the honored one.\"', 'art'),
('PR6', 'SE1', 'Action Figure Hu Tao', 5000.00, 1, 2.00, 'Bring home the fiery charm and playful mischief of Hu Tao, the 77th Director of the Wangsheng Funeral Parlor, with this premium collectible action figure. Sculpted with dynamic detail and rich paintwork, Hu Tao is captured mid-pose—playfully wielding her polearm, her iconic ghost companion floating beside her. A must-have for any Genshin Impact fan or anime figure collector!\r\n\r\n🧧 Height: Approx. 9.8 inches (1/7 scale)\r\n\r\n🎨 Finish: Hand-painted with high-fidelity color and shading\r\n\r\n🌸 Details: Includes hat, ghost buddy, flame effects, and base\r\n\r\n📦 Packaging: Collector’s box with Hu Tao-themed artwork\r\n\r\n💥 Articulation: Non-articulated (static pose for display)\r\n\r\n👻 \"A bright moon aloft amid the vast, clear skies... Moments like these are just perfect for ghost stories!\"\r\n\r\n', 'collectibles'),
('PR7', 'SE1', 'Action Figure Hu Tao', 20000.00, 1, 2.00, 'Bring home the fiery charm and playful mischief of Hu Tao, the 77th Director of the Wangsheng Funeral Parlor, with this premium collectible action figure. Sculpted with dynamic detail and rich paintwork, Hu Tao is captured mid-pose—playfully wielding her polearm, her iconic ghost companion floating beside her. A must-have for any Genshin Impact fan or anime figure collector!\r\n\r\n🧧 Height: Approx. 9.8 inches (1/7 scale)\r\n\r\n🎨 Finish: Hand-painted with high-fidelity color and shading\r\n\r\n🌸 Details: Includes hat, ghost buddy, flame effects, and base\r\n\r\n📦 Packaging: Collector’s box with Hu Tao-themed artwork\r\n\r\n💥 Articulation: Non-articulated (static pose for display)\r\n\r\n👻 \"A bright moon aloft amid the vast, clear skies... Moments like these are just perfect for ghost stories!\"\r\n\r\n', 'collectibles'),
('PR8', 'SE1', 'Action Figure Monkey D. Luffy', 50000.00, 1, 5.00, 'Set sail on the Grand Line with the fearless captain of the Straw Hat Pirates, Monkey D. Luffy! This highly detailed action figure captures Luffy in all his glory — from his signature straw hat to his iconic “Gomu Gomu no” poses. Made for collectors and One Piece fans, this figure is ready to bring Luffy’s indomitable spirit straight into your collection.\r\n\r\n🏴‍☠️ Height: 7 inches (scale varies based on pose)\r\n\r\n🧑‍🍳 Details: Luffy’s authentic red vest, blue shorts, and straw hat\r\n\r\n💪 Pose Options: Includes interchangeable hands for different iconic action poses (Gomu Gomu no Pistol, Gear Second, etc.)\r\n\r\n🔥 Material: High-quality PVC with realistic details and shading\r\n\r\n🧳 Packaging: Premium box featuring One Piece artwork and logo\r\n\r\n🔄 Articulation: Fully articulated for dynamic posing\r\n\r\n⚓ \"I\'m gonna be King of the Pirates!\"', 'collectibles'),
('PR9', 'SE1', 'Action Figure', 60000.00, 1, 10.00, 'Set sail on the Grand Line with the fearless captain of the Straw Hat Pirates, Monkey D. Luffy! This highly detailed action figure captures Luffy in all his glory — from his signature straw hat to his iconic “Gomu Gomu no” poses. Made for collectors and One Piece fans, this figure is ready to bring Luffy’s indomitable spirit straight into your collection.\r\n\r\n🏴‍☠️ Height: 7 inches (scale varies based on pose)\r\n\r\n🧑‍🍳 Details: Luffy’s authentic red vest, blue shorts, and straw hat\r\n\r\n💪 Pose Options: Includes interchangeable hands for different iconic action poses (Gomu Gomu no Pistol, Gear Second, etc.)\r\n\r\n🔥 Material: High-quality PVC with realistic details and shading\r\n\r\n🧳 Packaging: Premium box featuring One Piece artwork and logo\r\n\r\n🔄 Articulation: Fully articulated for dynamic posing\r\n\r\n⚓ \"I\'m gonna be King of the Pirates!\"', 'collectibles');

